from pathlib import Path
import re
root=Path('.')
for p in sorted(Path('docs/adr').glob('*.md')):
 s=p.read_text()
 print(f'{p}: {len(s.split())} words')
 for label,target in re.findall(r'\[([^\]]+)\]\(([^)]+)\)',s):
  if '://' in target or target.startswith('#'): continue
  q=p.parent/target.split('#')[0]
  if not q.exists(): print(f'  MISSING {label}: {target}')
print('Available files:')
for p in sorted(root.rglob('*')):
 if p.is_file(): print(p)
